#!/usr/bin/env python3
"""Exact builtin kernel axiom inventory; not a complete source or full gate."""
import json
from pathlib import Path
import re
import sys
PINS = {'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.spin_turn': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.spin_target_all': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.spin_represented_all': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.condition_failure_all': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.body_failed': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.failure_cost': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.failure_need': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.body_failure_all': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.not_complete_at_two': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.wrong_one_source': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.first_snapshot': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.wrong_one_cursor': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.wrong_final_old_alias': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.failure_not_fault': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.protected_scalar_not_private': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.old_contents_change': ['Classical.choice', 'Quot.sound', 'propext'], 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.failure_code': ['Classical.choice', 'Quot.sound', 'propext']}
NAMES = ['Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.spin_turn', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.spin_target_all', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.spin_represented_all', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.condition_failure_all', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.body_failed', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.failure_cost', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.failure_need', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.body_failure_all', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.not_complete_at_two', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.wrong_one_source', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.first_snapshot', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.wrong_one_cursor', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.wrong_final_old_alias', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.failure_not_fault', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.protected_scalar_not_private', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.old_contents_change', 'Solidity.Backend.InternalFlow.LoopTargetChecks.CallerPrefixes.failure_code']
def check(text):
    if re.search(r"(?:^|\n).*?(?:error:|error\(|sorryAx)",text):
        raise ValueError("Lean diagnostic or untrusted axiom")
    rows = [(n,sorted(x.strip()for x in a.split(',')if x.strip()))
        for n,a in re.findall(r"'([^']+)' (?:depends on axioms:\s*\[([^\]]*)\]|does not depend on any axioms)",text)]
    if rows != [(n,PINS[n])for n in NAMES]:
        raise ValueError("missing, extra, duplicate, reordered or changed axiom report")
    return len(rows)
log = Path(sys.argv[1]).read_text()
print(json.dumps({'status':'pass','reports':check(log)}))
